#include "kstationControllerInterruptRuntime.h"
#include <array>
#include <cstdio>
#include <fstream>
#include <memory>
#include <stdexcept>
#include <vector>
void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}
int main(int argc,char**argv){try{if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};check(rom.size()==49728,"rom");auto d=std::make_unique<kstation::ControllerDeviceState>();d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);kstation::ControllerInterruptRuntime irq;check(irq.bindVerifiedFirmware(*d,rom.data(),rom.size()),"irq bind");unsigned checks=0;for(auto range:{std::pair{0x70u,0x74u},std::pair{0x98u,0x9cu},std::pair{0xd0u,0xdcu},std::pair{0xf0u,0xf4u}})for(auto address=range.first;address<range.second;++address)for(auto alias:{0u,0x400000u,0x1000000u,0x1400000u})for(unsigned width:{1u,2u,4u})for(unsigned overlap=0;overlap<width;++overlap){auto start=address+alias-overlap;std::array<uint8_t,4>before{};for(unsigned i=0;i<width;++i)before[i]=d->readResource(start+i);auto old=d->cycles;bool rejected=false;try{if(width==1)d->write8(start,0xa5);else if(width==2)d->write16(start,0xa5a5);else d->write32(start,0xa5a5a5a5);}catch(const std::logic_error&){rejected=true;}check(rejected&&d->cycles==old,"guard before write");for(unsigned i=0;i<width;++i)check(d->readResource(start+i)==before[i],"partial vector mutation");++checks;}for(auto a:{0u,5u,6u,0x4eu,0x4fu,0x50u,0x58u,0x79u,0x7au,0x7bu,0x7eu,0x7fu})for(auto alias:{0u,0x400000u}){auto address=a+alias;auto old=d->readResource(address);d->writeResource(address,uint8_t(old^1));check(d->readResource(address)==uint8_t(old^1),"live unused vector");d->writeResource(address,old);}for(unsigned alias:{0u,0x400000u}){auto bad=std::make_unique<kstation::ControllerDeviceState>();bad->loadMemory(rom.data(),rom.size(),0);bad->loadMemory(rom.data(),rom.size(),0x400000);bad->memory[alias+0x70]^=1;kstation::ControllerInterruptRuntime rejected;check(!rejected.bindVerifiedFirmware(*bad,rom.data(),rom.size())&&!bad->hasImmutableBindings(),"mismatched vector bound");}std::printf("{\"passed\":true,\"guard_checks\":%u,\"live_unused_checks\":24}\n",checks);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
